package main

import (
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"os/exec"
	"strings"
	"text/template"
)

type DeployRequest struct {
	ServiceName string `json:"service_name"`
	Version     string `json:"version"`
	Namespace   string `json:"namespace"`
	HelmValues  string `json:"helm_values"`
	DryRun      bool   `json:"dry_run"`
}

type DeployResponse struct {
	Status  string `json:"status"`
	Output  string `json:"output"`
	Message string `json:"message"`
}

var helmTemplate = `helm upgrade --install {{ .ServiceName }} ./charts/{{ .ServiceName }} \
  --namespace {{ .Namespace }} \
  --set image.tag={{ .Version }} \
  {{ .HelmValues }} \
  {{ if .DryRun }}--dry-run{{ end }}`

func validateServiceName(name string) bool {
	// Only allow alphanumeric and hyphens
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-') {
			return false
		}
	}
	return len(name) > 0 && len(name) <= 63
}

func validateNamespace(ns string) bool {
	allowed := map[string]bool{"staging": true, "production": true, "canary": true}
	return allowed[ns]
}

func auditLog(req DeployRequest, remoteAddr string) {
	logEntry := fmt.Sprintf("[AUDIT] deploy request from=%s service=%s ns=%s version=%s dry_run=%v\n",
		remoteAddr, req.ServiceName, req.Namespace, req.Version, req.DryRun)
	f, err := os.OpenFile("/var/log/deployer/audit.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err == nil {
		defer f.Close()
		f.WriteString(logEntry)
	}
}

func deployHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	var req DeployRequest
	if err := json.Unmarshal(body, &req); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}

	if !validateServiceName(req.ServiceName) {
		http.Error(w, "invalid service name", http.StatusBadRequest)
		return
	}

	if !validateNamespace(req.Namespace) {
		http.Error(w, "invalid namespace", http.StatusBadRequest)
		return
	}

	// Version validation - semver-ish
	if len(req.Version) == 0 || len(req.Version) > 128 {
		http.Error(w, "invalid version", http.StatusBadRequest)
		return
	}

	auditLog(req, r.RemoteAddr)

	// Build command from template
	tmpl, err := template.New("helm").Parse(helmTemplate)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	var cmdBuf strings.Builder
	if err := tmpl.Execute(&cmdBuf, req); err != nil {
		http.Error(w, "template error", http.StatusInternalServerError)
		return
	}

	cmdStr := cmdBuf.String()
	log.Printf("Executing: %s", cmdStr)

	cmd := exec.Command("bash", "-c", cmdStr)
	cmd.Env = append(os.Environ(), "KUBECONFIG=/etc/deployer/kubeconfig")
	output, err := cmd.CombinedOutput()

	resp := DeployResponse{
		Output: string(output),
	}
	if err != nil {
		resp.Status = "error"
		resp.Message = err.Error()
	} else {
		resp.Status = "success"
		resp.Message = "deployment initiated"
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/deploy", deployHandler)
	mux.HandleFunc("/health", healthHandler)

	tlsCert := os.Getenv("TLS_CERT_PATH")
	tlsKey := os.Getenv("TLS_KEY_PATH")

	server := &http.Server{
		Addr:    ":8443",
		Handler: mux,
		TLSConfig: &tls.Config{
			MinVersion: tls.VersionTLS12,
		},
	}

	log.Printf("Starting deploy-controller on :8443")
	if err := server.ListenAndServeTLS(tlsCert, tlsKey); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
